<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?>
<dl class="ps-coa-metric-grid">
	<div><dt><?php esc_html_e( 'Purity', 'pepselect-coa-archive' ); ?></dt><dd><?php echo '' !== $test['purity_percentage'] ? esc_html( $test['purity_percentage'] . '%' ) : esc_html__( 'Not reported', 'pepselect-coa-archive' ); ?></dd><?php if ( $test['purity_method'] ) : ?><span><?php echo esc_html( $test['purity_method'] ); ?></span><?php endif; ?><?php if ( $test['purity_status']['value'] ) : ?><?php $status = $test['purity_status']; include pepselect_coa_template_path( 'partials/status-indicator.php' ); ?><?php endif; ?></div>
	<div><dt><?php esc_html_e( 'Average net content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo esc_html( trim( $test['average_net_content'] . ' ' . $test['content_unit'] ) ?: __( 'Not reported', 'pepselect-coa-archive' ) ); ?></dd><?php if ( $test['minimum_net_content'] || $test['maximum_net_content'] ) : ?><span><?php echo esc_html( sprintf( __( 'Range %1$s–%2$s %3$s', 'pepselect-coa-archive' ), $test['minimum_net_content'], $test['maximum_net_content'], $test['content_unit'] ) ); ?></span><?php endif; ?></div>
	<div><dt><?php esc_html_e( 'Labeled content', 'pepselect-coa-archive' ); ?></dt><dd><?php echo esc_html( $test['claimed_content'] ? trim( $test['claimed_content'] . ' ' . $test['content_unit'] ) : __( 'Not reported', 'pepselect-coa-archive' ) ); ?></dd></div>
	<div><dt><?php esc_html_e( 'Vials tested', 'pepselect-coa-archive' ); ?></dt><dd><?php echo esc_html( $test['vials_tested'] ?: __( 'Not reported', 'pepselect-coa-archive' ) ); ?></dd></div>
</dl>
